Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net/mlx5: Bridge, fix multicast packets sent to uplink

To enable multicast packets which are offloaded in bridge multicast
offload mode to be sent also to uplink, FTE bit uplink_hairpin_en should
be set. Add this bit to FTE for the bridge multicast offload rules.

Fixes: 18c2916cee12 ("net/mlx5: Bridge, snoop igmp/mld packets")
Signed-off-by: Moshe Shemesh <moshe@nvidia.com>
Reviewed-by: Gal Pressman <gal@nvidia.com>
Signed-off-by: Saeed Mahameed <saeedm@nvidia.com>

Here is the root cause:
The bug was caused by the absence of the `uplink_hairpin_en` flag in the flow context for multicast packets in bridge multicast offload mode, which prevented these packets from being sent to the uplink. This oversight meant that multicast packets were not properly configured to utilize the uplink path, leading to their failure to reach the intended destination.

Here is the patch:

 static struct mlx5_flow_handle *
 mlx5_esw_bridge_mdb_flow_create(u16 esw_owner_vhca_id, struct mlx5_esw_bridge_mdb_entry *entry,
 				struct mlx5_esw_bridge *bridge)
 {
 	struct mlx5_flow_act flow_act = {
 		.action = MLX5_FLOW_CONTEXT_ACTION_FWD_DEST,
 		.flags = FLOW_ACT_NO_APPEND | FLOW_ACT_IGNORE_FLOW_LEVEL,
 	};
 	int num_dests = entry->num_ports, i = 0;
 	struct mlx5_flow_destination *dests;
 	struct mlx5_esw_bridge_port *port;
 	struct mlx5_flow_spec *rule_spec;
 	struct mlx5_flow_handle *handle;
 	u8 *dmac_v, *dmac_c;
 	unsigned long idx;

 	rule_spec = kvzalloc(sizeof(*rule_spec), GFP_KERNEL);
 	if (!rule_spec)
 		return ERR_PTR(-ENOMEM);

 	dests = kvcalloc(num_dests, sizeof(*dests), GFP_KERNEL);
 	if (!dests) {
 		kvfree(rule_spec);
 		return ERR_PTR(-ENOMEM);
 	}

 	xa_for_each(&entry->ports, idx, port) {
 		dests[i].type = MLX5_FLOW_DESTINATION_TYPE_FLOW_TABLE;
 		dests[i].ft = port->mcast.ft;
 		if (port->vport_num == MLX5_VPORT_UPLINK)
 			dests[i].ft->flags |= MLX5_FLOW_TABLE_UPLINK_VPORT;
 		i++;
 	}

+	rule_spec->flow_context.flags |= FLOW_CONTEXT_UPLINK_HAIRPIN_EN;
 	rule_spec->match_criteria_enable = MLX5_MATCH_OUTER_HEADERS;
 	dmac_v = MLX5_ADDR_OF(fte_match_param, rule_spec->match_value, outer_headers.dmac_47_16);
 	ether_addr_copy(dmac_v, entry->key.addr);
 	dmac_c = MLX5_ADDR_OF(fte_match_param, rule_spec->match_criteria, outer_headers.dmac_47_16);
 	eth_broadcast_addr(dmac_c);

 	if (entry->key.vid) {
 		if (bridge->vlan_proto == ETH_P_8021Q) {
 			MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria,
 					 outer_headers.cvlan_tag);
 			MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_value,
 					 outer_headers.cvlan_tag);
 		} else if (bridge->vlan_proto == ETH_P_8021AD) {
 			MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria,
 					 outer_headers.svlan_tag);
 			MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_value,
 					 outer_headers.svlan_tag);
 		}
 		MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria,
 				 outer_headers.first_vid);
 		MLX5_SET(fte_match_param, rule_spec->match_value, outer_headers.first_vid,
 			 entry->key.vid);
 	}

 	handle = mlx5_add_flow_rules(bridge->egress_ft, rule_spec, &flow_act, dests, num_dests);

 	kvfree(dests);
 	kvfree(rule_spec);
 	return handle;
 }


 static struct mlx5_flow_handle *
 mlx5_esw_bridge_mcast_vlan_flow_create(u16 vlan_proto, struct mlx5_esw_bridge_port *port,
 				       struct mlx5_esw_bridge_vlan *vlan)
 {
 	struct mlx5_flow_act flow_act = {
 		.action = MLX5_FLOW_CONTEXT_ACTION_FWD_DEST,
 		.flags = FLOW_ACT_NO_APPEND,
 	};
 	struct mlx5_flow_destination dest = {
 		.type = MLX5_FLOW_DESTINATION_TYPE_VPORT,
 		.vport.num = port->vport_num,
 	};
 	struct mlx5_esw_bridge *bridge = port->bridge;
 	struct mlx5_flow_spec *rule_spec;
 	struct mlx5_flow_handle *handle;

 	rule_spec = kvzalloc(sizeof(*rule_spec), GFP_KERNEL);
 	if (!rule_spec)
 		return ERR_PTR(-ENOMEM);

+	rule_spec->flow_context.flags |= FLOW_CONTEXT_UPLINK_HAIRPIN_EN;
 	rule_spec->match_criteria_enable = MLX5_MATCH_OUTER_HEADERS;

 	flow_act.action |= MLX5_FLOW_CONTEXT_ACTION_PACKET_REFORMAT;
 	flow_act.pkt_reformat = vlan->pkt_reformat_pop;

 	if (vlan_proto == ETH_P_8021Q) {
 		MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria,
 				 outer_headers.cvlan_tag);
 		MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_value,
 				 outer_headers.cvlan_tag);
 	} else if (vlan_proto == ETH_P_8021AD) {
 		MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria,
 				 outer_headers.svlan_tag);
 		MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_value,
 				 outer_headers.svlan_tag);
 	}
 	MLX5_SET_TO_ONES(fte_match_param, rule_spec->match_criteria, outer_headers.first_vid);
 	MLX5_SET(fte_match_param, rule_spec->match_value, outer_headers.first_vid, vlan->vid);

 	if (MLX5_CAP_ESW(bridge->br_offloads->esw->dev, merged_eswitch)) {
 		dest.vport.flags = MLX5_FLOW_DEST_VPORT_VHCA_ID;
 		dest.vport.vhca_id = port->esw_owner_vhca_id;
 	}
 	handle = mlx5_add_flow_rules(port->mcast.ft, rule_spec, &flow_act, &dest, 1);

 	kvfree(rule_spec);
 	return handle;
 }


 static struct mlx5_flow_handle *
 mlx5_esw_bridge_mcast_fwd_flow_create(struct mlx5_esw_bridge_port *port)
 {
 	struct mlx5_flow_act flow_act = {
 		.action = MLX5_FLOW_CONTEXT_ACTION_FWD_DEST,
 		.flags = FLOW_ACT_NO_APPEND,
 	};
 	struct mlx5_flow_destination dest = {
 		.type = MLX5_FLOW_DESTINATION_TYPE_VPORT,
 		.vport.num = port->vport_num,
 	};
 	struct mlx5_esw_bridge *bridge = port->bridge;
 	struct mlx5_flow_spec *rule_spec;
 	struct mlx5_flow_handle *handle;

 	rule_spec = kvzalloc(sizeof(*rule_spec), GFP_KERNEL);
 	if (!rule_spec)
 		return ERR_PTR(-ENOMEM);

 	if (MLX5_CAP_ESW(bridge->br_offloads->esw->dev, merged_eswitch)) {
 		dest.vport.flags = MLX5_FLOW_DEST_VPORT_VHCA_ID;
 		dest.vport.vhca_id = port->esw_owner_vhca_id;
 	}
+	rule_spec->flow_context.flags |= FLOW_CONTEXT_UPLINK_HAIRPIN_EN;
 	handle = mlx5_add_flow_rules(port->mcast.ft, rule_spec, &flow_act, &dest, 1);

 	kvfree(rule_spec);
 	return handle;
 }



